<?php
session_start();if(!isset($_SESSION['student_id'])){header('Location: index.php');exit;}require 'Includes/dbcon.php';$student=(int)$_SESSION['student_id'];$stmt=$con->prepare('SELECT score,total_questions,date_taken FROM results WHERE student_id=? ORDER BY date_taken DESC,id DESC LIMIT 1');$stmt->bind_param('i',$student);$stmt->execute();$r=$stmt->get_result()->fetch_assoc();$pageTitle='Examination Result | FountainTest';include 'Includes/header.php';?>
<div class="auth-wrap"><div class="card text-center"><span class="pill align-self-center">ASSESSMENT SUMMARY</span><h1 class="h3 mt-3">Your latest result</h1><?php if(!$r):?><p class="muted my-3">You have not completed an examination yet. Your result will appear here after your first attempt.</p><a href="exam.php" class="btn btn-success">Start an examination</a><?php else:$percent=(int)$r['total_questions']>0?round(((int)$r['score']/(int)$r['total_questions'])*100):0;?><div class="result-score mt-3"><?=$percent?>%</div><p class="muted">Overall performance</p><div class="row g-3 text-start my-3"><div class="col-6"><div class="stat-card"><div class="stat-label">Correct answers</div><div class="stat-value"><?=(int)$r['score']?> / <?=(int)$r['total_questions']?></div></div></div><div class="col-6"><div class="stat-card"><div class="stat-label">Date completed</div><div class="fw-bold mt-2"><?=htmlspecialchars(date('M j, Y',strtotime($r['date_taken'])))?></div></div></div></div><div class="progress mb-4"><div class="progress-bar" style="width:<?=$percent?>%"></div></div><a href="dashboard.php" class="btn btn-success w-100 mb-2">Return to dashboard</a><a href="exam.php" class="btn btn-outline-success w-100">Take another examination</a><?php endif;?></div></div><?php include 'Includes/footer.php';?>
